#!/usr/bin/env bash
# step95 — Batch 1: fix duplicate "WhatsApp verified" message (webhook was both
# replying AND queuing the same message) + reword it (no empty Ref). The bot's
# instant reply is now the only confirmation. Idempotent; rolls back whatsapp.js.
set -euo pipefail
APP=/opt/gsz
TS=$(date +%Y%m%d-%H%M%S)
BAK=$APP/.bak-step95-$TS
mkdir -p "$BAK/routes"
cp "$APP/routes/whatsapp.js" "$BAK/routes/whatsapp.js"
restore(){ echo "!! rollback"; cp "$BAK/routes/whatsapp.js" "$APP/routes/whatsapp.js"; pm2 restart gsz --update-env >/dev/null 2>&1 || true; }
trap 'restore' ERR
cd "$APP"

echo "==> overwrite whatsapp.js (no duplicate verify message)"
base64 -d > "$APP/routes/whatsapp.js" <<'B64'

B64
node --check "$APP/routes/whatsapp.js"

echo "==> reword verification_success template"
node <<'NODE'
require('dotenv').config();
const { Pool } = require('pg');
const p = new Pool({ host:process.env.DB_HOST, port:process.env.DB_PORT, database:process.env.DB_NAME, user:process.env.DB_USER, password:process.env.DB_PASS });
p.query("UPDATE wa_templates SET body=$1, updated_at=now() WHERE key='whatsapp.verification_success'",
  ["✅ Your WhatsApp is verified for {{site_name}}. You'll get your order updates and trial details right here."])
  .then(r=>{ console.log('   template updated ('+r.rowCount+')'); return p.end(); }).catch(e=>{ console.error(e.message); p.end(); process.exit(1); });
NODE

echo "==> restart + health"; pm2 restart gsz --update-env >/dev/null; sleep 3
grep -q '</html>' <<<"$(curl -s -m 15 http://127.0.0.1:3900/ || true)" || { echo "!! home broken"; false; }
trap - ERR
echo "==> step95 OK — single verify message, reworded. Backup: $BAK"
echo "   Also update the bot for speed:  git pull  then  bash step79.sh"
